public record UserProfile(String id, String email) {
    public UserProfile {
        Objects.requireNonNull(id, "ID cannot be null");
        if (!email.contains("@")) throw new IllegalArgumentException("Invalid email");
    }
}

// Use functional interfaces to keep logic declarative
public List<String> getActiveUserEmails(List<UserProfile> users) {
    return users.stream()
                .map(UserProfile::email)
                .filter(email -> email.endsWith(".com"))
                .toList();
}
